          "jsCode": "// ============================================\n// CODE NODE: PROCESSADOR DE OUTPUT DO AI AGENT\n// Versão: 4.0 - Tratamento robusto de JSON com smart quotes\n// ============================================\n\n// SEÇÃO 1: CAPTURA DE DADOS\nconst agentOutput = $input.first().json.output;\nconst intelligenceData = $('Edit Fields1').first().json;\n\n// SEÇÃO 2: FUNÇÕES AUXILIARES\n// ============================================\n\nfunction sanitizeJsonString(str) {\n  if (!str) return str;\n  \n  // 1. Substituir smart quotes por aspas normais\n  str = str\n    .replace(/[\\u201C\\u201D\\u201E\\u201F\\u2033\\u2036]/g, '\"')  // Smart double quotes\n    .replace(/[\\u2018\\u2019\\u201A\\u201B\\u2032\\u2035]/g, \"'\")  // Smart single quotes\n    .replace(/[\\u00AB\\u00BB]/g, '\"')  // Guillemets\n    .replace(/[\\u2014\\u2013]/g, '-')  // Em dash, en dash\n    .replace(/\\u2026/g, '...')  // Ellipsis\n    .replace(/\\u00A0/g, ' ');  // Non-breaking space\n  \n  // 2. Remover caracteres de controle\n  str = str.replace(/[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]/g, '');\n  \n  return str;\n}\n\nfunction extractJsonFromOutput(output) {\n  if (!output) {\n    throw new Error('Output do AI Agent está vazio');\n  }\n  \n  // 1. Sanitizar primeiro (smart quotes, etc)\n  let cleaned = sanitizeJsonString(output);\n  \n  // 2. Remover markdown code blocks\n  cleaned = cleaned\n    .replace(/^```json\\s*\\n?/gi, '')\n    .replace(/^```\\s*\\n?/gi, '')\n    .replace(/\\n?```\\s*$/gi, '')\n    .trim();\n  \n  // 3. Encontrar o JSON se não começa com { ou [\n  if (!cleaned.startsWith('{') && !cleaned.startsWith('[')) {\n    const jsonMatch = cleaned.match(/\\{[\\s\\S]*\\}/);\n    if (jsonMatch) {\n      cleaned = jsonMatch[0];\n    } else {\n      throw new Error('Não foi possível encontrar JSON válido no output');\n    }\n  }\n  \n  // 4. Primeira tentativa de parse\n  try {\n    const parsed = JSON.parse(cleaned);\n    return { json: cleaned, parsed };\n  } catch (firstError) {\n    console.log('Primeira tentativa falhou:', firstError.message);\n  }\n  \n  // 5. Tentar corrigir newlines não escapados dentro de strings\n  let fixedJson = cleaned;\n  for (let i = 0; i < 5; i++) {\n    fixedJson = fixedJson.replace(/\"([^\"]*?)\\n([^\"]*?)\"/g, (match, p1, p2) => {\n      return '\"' + p1 + '\\\\n' + p2 + '\"';\n    });\n  }\n  \n  // 6. Segunda tentativa\n  try {\n    const parsed = JSON.parse(fixedJson);\n    console.log('Parse bem sucedido após correção de newlines');\n    return { json: fixedJson, parsed };\n  } catch (secondError) {\n    console.log('Segunda tentativa falhou:', secondError.message);\n  }\n  \n  // 7. Última tentativa: remover todas as quebras de linha\n  let lastResort = cleaned\n    .replace(/\\r\\n/g, ' ')\n    .replace(/\\n/g, ' ')\n    .replace(/\\r/g, ' ')\n    .replace(/\\t/g, ' ')\n    .replace(/\\s+/g, ' ');\n  \n  try {\n    const parsed = JSON.parse(lastResort);\n    console.log('Parse bem sucedido após remover quebras de linha');\n    return { json: lastResort, parsed };\n  } catch (finalError) {\n    console.error('Todas as tentativas falharam');\n    console.error('Erro final:', finalError.message);\n    throw new Error('Falha ao fazer parse do JSON: ' + finalError.message);\n  }\n}\n\nfunction validateBlogPost(post) {\n  const requiredFields = ['title', 'slug', 'excerpt', 'content_html', 'categories', 'tags', 'structured_data'];\n  const missingFields = [];\n  \n  for (const field of requiredFields) {\n    if (!post[field]) {\n      missingFields.push(field);\n      continue;\n    }\n    if ((field === 'categories' || field === 'tags') && \n        (!Array.isArray(post[field]) || post[field].length === 0)) {\n      missingFields.push(field);\n    }\n  }\n  \n  if (missingFields.length > 0) {\n    throw new Error('Campos obrigatórios faltando: ' + missingFields.join(', '));\n  }\n  return true;\n}\n\nfunction generateUniqueSlug(baseText, intelligenceId) {\n  let cleanSlug = (baseText || 'post')\n    .toLowerCase()\n    .normalize('NFD')\n    .replace(/[\\u0300-\\u036f]/g, '')\n    .replace(/[^a-z0-9]+/g, '-')\n    .replace(/^-+|-+$/g, '')\n    .replace(/--+/g, '-');\n  \n  if (cleanSlug.length > 50) {\n    cleanSlug = cleanSlug.substring(0, 50).replace(/-$/, '');\n  }\n  \n  const now = new Date();\n  const dateStr = now.getFullYear() + String(now.getMonth() + 1).padStart(2, '0') + String(now.getDate()).padStart(2, '0');\n  const timeStr = String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0');\n  const uniqueId = intelligenceId ? intelligenceId.replace(/-/g, '').slice(-6).toLowerCase() : String(Math.floor(100000 + Math.random() * 900000));\n  \n  return cleanSlug + '-' + dateStr + '-' + timeStr + '-' + uniqueId;\n}\n\n// SEÇÃO 3: PROCESSAMENTO PRINCIPAL\n// ============================================\n\nlet blogPost;\n\ntry {\n  const result = extractJsonFromOutput(agentOutput);\n  blogPost = result.parsed;\n  validateBlogPost(blogPost);\n} catch (error) {\n  console.error('Erro no processamento:', error);\n  return {\n    error: true,\n    error_type: error.name,\n    message: 'Erro ao processar output do AI Agent: ' + error.message,\n    raw_output: agentOutput ? agentOutput.substring(0, 500) : 'Output vazio',\n    timestamp: new Date().toISOString()\n  };\n}\n\n// SEÇÃO 4: PREPARAR DADOS\n// ============================================\n\nconst uniqueSlug = generateUniqueSlug(\n  blogPost.slug || blogPost.title,\n  intelligenceData.intelligence_id || intelligenceData.id\n);\n\nconst now = new Date().toISOString();\n\n// SEÇÃO 5: SEPARAÇÃO PARA AS 3 TABELAS\n// ============================================\n\nconst content_post = {\n  intelligence_id: intelligenceData.intelligence_id || intelligenceData.id,\n  tier: intelligenceData.tier || 'TIER_2',\n  title: blogPost.title,\n  slug: uniqueSlug,\n  excerpt: blogPost.excerpt,\n  content_html: blogPost.content_html,\n  content_markdown: blogPost.content_markdown || '',\n  word_count: parseInt(blogPost.word_count) || 0,\n  reading_time_minutes: parseInt(blogPost.reading_time_minutes) || Math.ceil((parseInt(blogPost.word_count) || 0) / 200),\n  post_type: 'archive',\n  original_source: intelligenceData.source || 'Market Intelligence',\n  original_date: intelligenceData.created_at || null,\n  created_at: now,\n  updated_at: now\n};\n\nconst content_metadata = {\n  meta_title: blogPost.meta_title,\n  meta_description: blogPost.meta_description,\n  categories: blogPost.categories || [],\n  tags: blogPost.tags || [],\n  structured_data: blogPost.structured_data || {}\n};\n\nconst content_workflow = {\n  status: 'draft',\n  review_notes: null\n};\n\nconsole.log('Post processado com sucesso:', {\n  intelligence_id: content_post.intelligence_id,\n  title: content_post.title,\n  slug: content_post.slug\n});\n\nreturn {\n  content_post,\n  content_metadata,\n  content_workflow\n};"
        },
