          "parameters": {
            "jsCode": "// Pega os dados da notícia processada\nconst intelligence = $json;\n\n// Função auxiliar para extrair fonte do título se existir\nfunction extractSource(title) {\n  if (!title) return 'Market Intelligence';\n  \n  // Tenta extrair fonte de padrões comuns\n  if (title.includes('Platts')) return 'Platts';\n  if (title.includes('GFI')) return 'GFI';\n  if (title.includes('Reuters')) return 'Reuters';\n  if (title.includes('Bloomberg')) return 'Bloomberg';\n  if (title.includes('S&P Global')) return 'S&P Global';\n  \n  // Tenta pegar primeira parte antes de hífen ou dois pontos\n  const match = title.match(/^([^-:]+)/);\n  return match ? match[1].trim() : 'Market Intelligence';\n}\n\n// Função para garantir que temos um array válido\nfunction ensureArray(value) {\n  if (!value) return [];\n  if (Array.isArray(value)) return value;\n  return [value];\n}\n\n// Função para formatar data em português\nfunction formatDatePT(dateStr) {\n  if (!dateStr) return new Date().toLocaleDateString('pt-BR');\n  \n  const date = new Date(dateStr);\n  return date.toLocaleDateString('pt-BR', {\n    day: '2-digit',\n    month: '2-digit',\n    year: 'numeric',\n    hour: '2-digit',\n    minute: '2-digit'\n  });\n}\n\n// Função para criar um título se não existir\nfunction generateTitle(intel) {\n  // Se já tem título, usa ele\n  if (intel.title) return intel.title;\n  \n  // Tenta criar título baseado em outros campos\n  if (intel.category === 'price_update') {\n    return `Atualização de Preços - ${formatDatePT(intel.created_at)}`;\n  }\n  \n  if (intel.category === 'corporate_news' && intel.companies?.length > 0) {\n    return `Notícias Corporativas: ${intel.companies[0]}`;\n  }\n  \n  if (intel.subcategory) {\n    // Transforma snake_case em título legível\n    const readable = intel.subcategory\n      .replace(/_/g, ' ')\n      .replace(/\\b\\w/g, l => l.toUpperCase());\n    return readable;\n  }\n  \n  // Título genérico baseado no tier\n  return `${intel.tier} Market Update - ${formatDatePT(intel.created_at)}`;\n}\n\n// Função para criar conteúdo descritivo se não existir\nfunction generateContent(intel) {\n  // Se tem original_content, retorna\n  if (intel.original_content) return intel.original_content;\n  \n  // Se tem key_facts, cria um resumo a partir deles\n  if (intel.key_facts_pt && intel.key_facts_pt.length > 0) {\n    return intel.key_facts_pt.join(' ');\n  }\n  \n  // Se tem summary_pt, usa ele\n  if (intel.summary_pt) return intel.summary_pt;\n  \n  // Conteúdo genérico baseado na categoria\n  const categoryDescriptions = {\n    'price_update': 'Atualização de preços do mercado de minério de ferro.',\n    'trade_flow': 'Movimentação de volumes e negociações no mercado.',\n    'corporate_news': 'Notícias sobre empresas do setor de mineração e siderurgia.',\n    'market_sentiment': 'Análise do sentimento e tendências do mercado.',\n    'supply_demand': 'Informações sobre oferta e demanda de minério de ferro.',\n    'policy': 'Mudanças regulatórias e políticas governamentais.'\n  };\n  \n  return categoryDescriptions[intel.category] || 'Informação do mercado de minério de ferro.';\n}\n\n// Prepara os dados de forma robusta\nconst preparedData = {\n  // Identificação\n  intelligence_id: intelligence.id,\n  raw_id: intelligence.raw_id,\n  \n  // Classificação (sempre presente)\n  tier: intelligence.tier || 'TIER_2',\n  category: intelligence.category || 'market_update',\n  subcategory: intelligence.subcategory || '',\n  \n  // Temporalidade\n  created_at: intelligence.created_at || new Date().toISOString(),\n  time_sensitivity: intelligence.time_sensitivity || 'daily',\n  \n  // Conteúdo - com fallbacks inteligentes\n  original_title: generateTitle(intelligence),\n  title_exists: !!intelligence.title, // Flag para saber se título era original\n  \n  original_content: generateContent(intelligence),\n  content_exists: !!intelligence.original_content, // Flag para saber se conteúdo era original\n  \n  summary_pt: intelligence.summary_pt || \n    (intelligence.key_facts_pt && intelligence.key_facts_pt.length > 0 \n      ? intelligence.key_facts_pt[0] \n      : 'Informação relevante do mercado de minério de ferro.'),\n  \n  key_facts_pt: ensureArray(intelligence.key_facts_pt),\n  \n  // Entidades e métricas\n  companies: ensureArray(intelligence.companies),\n  regions: ensureArray(intelligence.regions),\n  \n  // Preços e spreads - mantém estrutura mesmo se vazio\n  spot_prices: intelligence.spot_prices || {},\n  spreads: intelligence.spreads || {},\n  \n  // Métricas de impacto\n  price_impact_score: intelligence.price_impact_score || 5,\n  volume_mentioned: intelligence.volume_mentioned || null,\n  \n  // Fonte extraída\n  source: extractSource(intelligence.title || intelligence.original_title),\n  \n  // Metadata adicional para o agente\n  metadata: {\n    has_complete_data: !!(intelligence.title && intelligence.original_content),\n    needs_enrichment: !intelligence.title || !intelligence.original_content,\n    processed_date: formatDatePT(intelligence.created_at)\n  }\n};\n\n// Log para debug (opcional - remova em produção)\nconsole.log(`Processando notícia:`, {\n  id: preparedData.intelligence_id,\n  tier: preparedData.tier,\n  has_title: preparedData.title_exists,\n  has_content: preparedData.content_exists,\n  facts_count: preparedData.key_facts_pt.length\n});\n\nreturn preparedData;"
          },
